type recorder struct{ got []forward.Forward }

func (r *recorder) Init() tea.Cmd { return nil }
func (r *recorder) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
	if m, ok := msg.(forward.ChangedMsg); ok {
