package netdiag

import (
	"strconv"
	"strings"

	"github.com/charmbracelet/bubbles/textinput"
	tea "github.com/charmbracelet/bubbletea"

	"github.com/anthnel/devdesk/internal/ui/theme"
)

// ForwardFormSubmitMsg carries a confirmed forward request (Rule 109).
type ForwardFormSubmitMsg struct {
	LocalPort int
	Target    string
}

// ForwardFormCancelMsg is sent when the form is dismissed.
type ForwardFormCancelMsg struct{}

// The form's fields, in the order ↑↓ walks them.
const (
	forwardFieldPort = iota
	forwardFieldTarget
	forwardFieldCount
)

// forwardLabelWidth pads the two labels to a common width so the chevrons line
// up, which is the whole of the alignment in a two-field form.
const forwardLabelWidth = 11

// ForwardForm asks for a local port and a target, and nothing else.
//
// It validates only that the port is a number, and deliberately not that it is
// above 1024, that the target parses, or that anything answers there. Every one
// of those rules lives in internal/forward, which is what actually enforces
// them; restating them here would be a second copy free to drift, and the one
// on screen would be the copy that is not enforcing anything. The registry's
// refusal reaches the user through the footer instead (Rule 128).
type ForwardForm struct {
	portInput   textinput.Model
	targetInput textinput.Model
	focused     int
	width       int
}

// NewForwardForm builds the form, focused on the port.
func NewForwardForm(width int) *ForwardForm {
	newInput := func(placeholder string, limit int) textinput.Model {
		ti := textinput.New()
		ti.CharLimit = limit
		ti.Placeholder = placeholder
		theme.StyleTextInput(&ti)
		return ti
	}

	f := &ForwardForm{
		portInput:   newInput("8080", 5),
		targetInput: newInput("host:port", 255),
		width:       width,
	}
	f.updateFocus()
	return f
}

// SetWidth keeps the form sized with the viewport (Rule 108).
func (f *ForwardForm) SetWidth(width int) { f.width = width }

// updateFocus gives the keyboard to the focused field and takes it from the
// others, which is what makes exactly one cursor visible.
func (f *ForwardForm) updateFocus() {
	inputs := []*textinput.Model{&f.portInput, &f.targetInput}
	for i, in := range inputs {
		if i == f.focused {
			in.Focus()
			continue
		}
		in.Blur()
	}
}

// Update handles the form's keys. ↑↓ move between fields, enter confirms and
// esc cancels (Rule 135); tab does nothing here, it belongs to the tabs.
func (f *ForwardForm) Update(msg tea.Msg) (*ForwardForm, tea.Cmd) {
	key, ok := msg.(tea.KeyMsg)
	if !ok {
		return f, nil
	}

	switch key.String() {
	case "up":
		f.focused = max(f.focused-1, 0)
		f.updateFocus()
		return f, nil
	case "down":
		f.focused = min(f.focused+1, forwardFieldCount-1)
		f.updateFocus()
		return f, nil
	case "esc":
		return f, func() tea.Msg { return ForwardFormCancelMsg{} }
	case "enter":
		return f, f.submit()
	}

	var cmd tea.Cmd
	if f.focused == forwardFieldPort {
		f.portInput, cmd = f.portInput.Update(msg)
		return f, cmd
	}
	f.targetInput, cmd = f.targetInput.Update(msg)
	return f, cmd
}

// submit turns the two fields into a request, or nil when the port is not a
// number — the one thing that has to be decided here, because the message
// carries an int and there is nothing to put in it otherwise.
func (f *ForwardForm) submit() tea.Cmd {
	port, err := strconv.Atoi(strings.TrimSpace(f.portInput.Value()))
	if err != nil {
		return nil
	}
	target := strings.TrimSpace(f.targetInput.Value())
	return func() tea.Msg {
		return ForwardFormSubmitMsg{LocalPort: port, Target: target}
	}
}

// PortIsANumber reports whether submit would produce anything. The model asks
// before calling submit so it can say why nothing happened rather than
// swallowing the keypress (Rule 130).
func (f *ForwardForm) PortIsANumber() bool {
	_, err := strconv.Atoi(strings.TrimSpace(f.portInput.Value()))
	return err == nil
}

// View renders the form in the viewport (Rule 112), opening on exactly one
// blank line (Rule 131) and carrying no inline help (Rule 134).
func (f *ForwardForm) View() string {
	lines := []string{
		theme.EmptyLineBg(f.width),
		f.renderField("Local port", f.portInput.View(), forwardFieldPort),
		f.renderField("Target", f.targetInput.View(), forwardFieldTarget),
	}
	return strings.Join(lines, "\n")
}

// renderField draws one single-line field: indicator, padded label, chevron,
// value (Rule 120). Single-line fields are separated by one newline, which
// strings.Join supplies (Rule 113).
func (f *ForwardForm) renderField(label, value string, field int) string {
	padded := label + strings.Repeat(" ", max(forwardLabelWidth-len([]rune(label)), 0))
	if f.focused == field {
		return theme.KeyStyle.Render(theme.IconCircleSmall+" "+padded+" "+theme.IconChevronRight+" ") + value
	}
	return theme.Bg("  "+padded+" "+theme.IconChevronRight+" ") + value
}

package netdiag

import (
	"fmt"
	"strconv"
	"time"

	"github.com/charmbracelet/lipgloss"
	tea "github.com/charmbracelet/bubbletea"

	"github.com/anthnel/devdesk/internal/forward"
	"github.com/anthnel/devdesk/internal/ui/components"
	"github.com/anthnel/devdesk/internal/ui/datatable"
	"github.com/anthnel/devdesk/internal/ui/keymap"
	"github.com/anthnel/devdesk/internal/ui/shortcut"
	"github.com/anthnel/devdesk/internal/ui/theme"
)

// The Forward tab: the open port redirections, and the form that opens one
// (§3.1).
//
// It holds no listener. The registry is the router's — a view is dropped whole
// by reinitializeViews on a config save and on a context switch, and a bound
// port going with it would be leaked in silence. This model asks
// (forward.Open / forward.Close / forward.Refresh) and is told
// (forward.ChangedMsg).

// forwardRefreshInterval is how often the tab asks for a fresh snapshot.
//
// It is a constant rather than a setting because the two things it shows move
// on their own — the connection counters — and neither is worth a context key
// (§3.1 keeps the forwards out of the configuration entirely). Two seconds is
// what the Ports tab defaults to, and the same reading is what makes them feel
// like one screen.
const forwardRefreshInterval = 2 * time.Second

// forwardTickMsg drives the snapshot chain.
type forwardTickMsg struct{}

func forwardTickCmd() tea.Cmd {
	return tea.Tick(forwardRefreshInterval, func(time.Time) tea.Msg { return forwardTickMsg{} })
}

// ForwardModel is the tab's state.
type ForwardModel struct {
	width  int
	height int

	table datatable.Model[forward.Forward]

	// form is non-nil while N's form has the screen (Rule 112).
	form *ForwardForm
	// confirmModal guards K. Stopping a forward drops the connections it is
	// carrying, which is not something to do on a mistyped key.
	confirmModal *components.ConfirmModal

	// ticking says a snapshot chain is alive. The chain runs only while there
	// is something to refresh and is restarted when a forward appears — the
	// shape of the router's job spinner (D5). Without it the tab would ask the
	// router for a broadcast every two seconds for the whole session, on a
	// table that is empty and cannot change on its own.
	ticking bool

	// footer is this tab's own message line, like every other tab's: a shared
	// one would let a message set here outlive the switch away.
	footer components.FooterMessage
}

// forwardColumns describes the table.
//
// Local and Target are what a forward *is* and never drop. Everything else is
// Optional, in the order it is worth losing: Total before Age before the
// error, since a count of everything ever carried is the least urgent of them
// (Rule 116 — a column gives way whole, never one cell at a time).
func forwardColumns() []datatable.Column[forward.Forward] {
	target := func(f forward.Forward) string { return f.Target }
	source := func(f forward.Forward) string {
		if f.Label == "" {
			return "-"
		}
		return f.Label
	}

	return []datatable.Column[forward.Forward]{
		{
			Title: "Local", Sizing: datatable.SizingFixed, MinWidth: 7,
			Cell:   func(f forward.Forward) string { return strconv.Itoa(f.LocalPort) },
			Search: func(f forward.Forward) string { return strconv.Itoa(f.LocalPort) },
		},
		{
			Title: "Target", Sizing: datatable.SizingContent, MinWidth: 20, Flex: 1,
			Cell: target, Search: target,
		},
		{
			Title: "Source", Sizing: datatable.SizingContent, MinWidth: 10, Optional: true,
			Cell: source, Search: source,
			// A forward whose target was typed has no source, and a "-" is an
			// absence rather than a value (Rule 122).
			Style: func(f forward.Forward) lipgloss.Style {
				if f.Label == "" {
					return theme.DimStyle
				}
				return lipgloss.NewStyle()
			},
		},
		{
			Title: "Live", Sizing: datatable.SizingFixed, MinWidth: 6,
			Cell:  func(f forward.Forward) string { return strconv.Itoa(f.Active) },
			Style: dimWhenZero(func(f forward.Forward) int { return f.Active }),
		},
		{
			Title: "Total", Sizing: datatable.SizingFixed, MinWidth: 7, Optional: true, DropFirst: true,
			Cell:  func(f forward.Forward) string { return strconv.FormatInt(f.Total, 10) },
			Style: dimWhenZero(func(f forward.Forward) int { return int(f.Total) }),
		},
		{
			Title: "Age", Sizing: datatable.SizingFixed, MinWidth: 9, Optional: true,
			Cell: func(f forward.Forward) string { return theme.TimeAgo(f.Opened) },
		},
		{
			Title: "Last error", Sizing: datatable.SizingContent, MinWidth: 12, Optional: true,
			Cell: func(f forward.Forward) string {
				if f.LastErr == "" {
					return "-"
				}
				return f.LastErr
			},
			// The healthy case is the majority one and gets no colour; the
			// absence of an error reads as an absence (Rule 122).
			Style: func(f forward.Forward) lipgloss.Style {
				if f.LastErr == "" {
					return theme.DimStyle
				}
				return theme.StatusErrorStyle
			},
		},
	}
}

// dimWhenZero greys a counter that has nothing to say (Rule 122).
func dimWhenZero(count func(forward.Forward) int) func(forward.Forward) lipgloss.Style {
	return func(f forward.Forward) lipgloss.Style {
		if count(f) == 0 {
			return theme.DimStyle
		}
		return lipgloss.NewStyle()
	}
}

// newForwardModel creates the tab.
func newForwardModel() *ForwardModel {
	return &ForwardModel{
		table: datatable.New(datatable.Config[forward.Forward]{
			Columns: forwardColumns(),
			// The registry already hands them over oldest first, which is the
			// order they were opened in — the one order a row does not move in
			// when another forward is added.
			SortColumn: -1,
		}),
	}
}

// InEditMode returns true when the form, the search box or the confirmation
// holds the keyboard.
func (fm *ForwardModel) InEditMode() bool {
	return fm.form != nil || fm.table.InEditMode() || fm.confirmModal != nil
}

// resize lays the table out. fm.height is the viewport content height the app
// sent (Rule 124); the filter bar lives in the footer, outside it (Rule 116).
func (fm *ForwardModel) resize(width, height int) {
	fm.width = width
	fm.height = height
	if width == 0 {
		return
	}
	if fm.form != nil {
		fm.form.SetWidth(width)
	}
	fm.table.Resize(width, max(height, 3))
}

func (fm *ForwardModel) update(msg tea.Msg) (*ForwardModel, tea.Cmd) {
	switch msg := msg.(type) {
	case forward.ChangedMsg:
		return fm.handleChanged(msg)
	case forwardTickMsg:
		return fm.handleTick()
	case ForwardFormSubmitMsg:
		return fm.handleFormSubmit(msg)
	case ForwardFormCancelMsg:
		fm.form = nil
		return fm, nil
	case components.ConfirmModalYesMsg:
		fm.confirmModal = nil
		return fm.closeSelected()
	case components.ConfirmModalNoMsg:
		fm.confirmModal = nil
		return fm, nil
	case tea.KeyMsg:
		return fm.handleKey(msg)
	}
	return fm, nil
}

// handleChanged takes the router's snapshot and restarts the chain if one is
// needed. The cursor and the scroll survive SetItems, which is what lets this
// run every two seconds.
func (fm *ForwardModel) handleChanged(msg forward.ChangedMsg) (*ForwardModel, tea.Cmd) {
	fm.table.SetItems(msg.Forwards)
	return fm, fm.ensureTick()
}

// ensureTick starts the chain when there is something to watch and none is
// alive. It is the one place a chain starts, so no path can leave two running.
func (fm *ForwardModel) ensureTick() tea.Cmd {
	if fm.ticking || len(fm.table.Items()) == 0 {
		return nil
	}
	fm.ticking = true
	return forwardTickCmd()
}

// handleTick asks the router for a snapshot and renews itself, or lets the
// chain die once the last forward is gone.
func (fm *ForwardModel) handleTick() (*ForwardModel, tea.Cmd) {
	if len(fm.table.Items()) == 0 {
		fm.ticking = false
		return fm, nil
	}
	return fm, tea.Batch(forward.Refresh, forwardTickCmd())
}

// handleFormSubmit closes the form and asks the router to open the forward.
// Every refusal is the registry's to give, and arrives at the footer.
func (fm *ForwardModel) handleFormSubmit(msg ForwardFormSubmitMsg) (*ForwardModel, tea.Cmd) {
	fm.form = nil
	return fm, forward.Open(msg.LocalPort, msg.Target, "")
}

func (fm *ForwardModel) handleKey(msg tea.KeyMsg) (*ForwardModel, tea.Cmd) {
	if fm.confirmModal != nil {
		var cmd tea.Cmd
		fm.confirmModal, cmd = fm.confirmModal.Update(msg)
		return fm, cmd
	}
	if fm.form != nil {
		return fm.handleFormKey(msg)
	}
	if fm.table.InEditMode() {
		cmd := fm.table.Update(msg)
		fm.table.GotoTop() // a narrowing query starts from the first match
		return fm, cmd
	}
	return fm.handleKeyNormal(msg)
}

// handleFormKey lets the form have the keyboard, and answers the one refusal
// the form itself decides rather than letting the keypress vanish (Rule 130).
func (fm *ForwardModel) handleFormKey(msg tea.KeyMsg) (*ForwardModel, tea.Cmd) {
	if msg.String() == "enter" && !fm.form.PortIsANumber() {
		return fm, fm.footer.Warn(reasonPortNotANumber)
	}
	var cmd tea.Cmd
	fm.form, cmd = fm.form.Update(msg)
	return fm, cmd
}

func (fm *ForwardModel) handleKeyNormal(msg tea.KeyMsg) (*ForwardModel, tea.Cmd) {
	switch msg.String() {
	case "up", "down", "pgup", "pgdown", "home", "end", "/":
		return fm, fm.table.Update(msg)
	case keymap.New:
		fm.form = NewForwardForm(fm.width)
		return fm, nil
	case keymap.Kill:
		return fm.confirmClose()
	}
	return fm, nil
}

// Why an action does not apply, written once so the header, the footer and the
// tests cannot drift apart on the wording (Rule 129 — English US).
const (
	reasonNoForwardRow   = "No forward selected"
	reasonPortNotANumber = "The local port has to be a number"
)

// closable reports whether K has a forward to stop (Rule 130).
func (fm *ForwardModel) closable() shortcut.Availability {
	if _, ok := fm.table.Selected(); !ok {
		return shortcut.Unavailable(reasonNoForwardRow)
	}
	return shortcut.Availability{}
}

// confirmClose asks before dropping the connections the forward is carrying.
func (fm *ForwardModel) confirmClose() (*ForwardModel, tea.Cmd) {
	if c := fm.closable(); !c.Enabled() {
		return fm, fm.footer.Warn(c.Reason)
	}
	entry, _ := fm.table.Selected()
	body := fmt.Sprintf("Stop forwarding %s to %s?", entry.Addr(), entry.Target)
	if entry.Active > 0 {
		body += fmt.Sprintf("\n\n%d connection(s) in progress will be dropped.", entry.Active)
	}
	fm.confirmModal = components.NewConfirmModal("Stop Forward", body)
	return fm, nil
}

// closeSelected asks the router to stop the forward, once confirmed.
func (fm *ForwardModel) closeSelected() (*ForwardModel, tea.Cmd) {
	entry, ok := fm.table.Selected()
	if !ok {
		return fm, nil
	}
	return fm, forward.Close(entry.ID)
}

// view renders the form when it is open (Rule 112), and otherwise the table —
// always the table, empty or not (Rule 139).
func (fm *ForwardModel) view() string {
	if fm.form != nil {
		return fm.form.View()
	}
	return fm.table.View()
}

// status is what the footer says when no message is pending: a state, derived
// every frame, never set with a timer (Rule 128).
func (fm *ForwardModel) status() components.Status {
	if fm.form != nil {
		return components.Status{Text: "Forwards listen on 127.0.0.1 only, on a port at or above 1024"}
	}
	if len(fm.table.Items()) == 0 {
		return components.Status{Text: "No forward open — N opens one"}
	}
	return components.Status{}
}

// summaryLine counts what is open, for the header (Rule 139).
func (fm *ForwardModel) summaryLine() string {
	return fmt.Sprintf("%d", len(fm.table.Items()))
}

result.output:
)

// Tab indices
const (
	tabDiagnostics = 0
	tabPorts       = 1
	tabInterfaces  = 2
)

// Form field indices.
//
// There were eleven, seven of them checkboxes selecting which tools to run.
// They asked the user to configure something the pipeline derives: the checks
=== New ===
func New(cfg *config.Config) *Model {
	targetIn := textinput.New()
	theme.StyleTextInput(&targetIn)
	targetIn.Placeholder = "hostname or IP address"
	targetIn.CharLimit = 256
	targetIn.Focus()

	portIn := textinput.New()
	theme.StyleTextInput(&portIn)
	portIn.Placeholder = defaultPort
	portIn.CharLimit = 10

	dnsIn := textinput.New()
	theme.StyleTextInput(&dnsIn)
	// Empty means the system resolver, and that is the answer the user cares
	// about: it is the one their own traffic uses. The old default read the
	// first nameserver out of /etc/resolv.conf, which does not exist on Windows.
	dnsIn.Placeholder = "system resolver"
	dnsIn.CharLimit = 64

	sp := spinner.New()
	sp.Spinner = spinner.Dot
	sp.Style = theme.SpinnerStyle()

	return &Model{
		config:          cfg,
		state:           StateInput,
		activeTab:       tabDiagnostics,
		portsModel:      newPortsModel(time.Duration(cfg.Network.PortsRefreshInterval) * time.Second),
		interfacesModel: newInterfacesModel(),
		targetInput:     targetIn,
		portInput:       portIn,
		dnsServerInput:  dnsIn,
		focusedField:    fieldTarget,
		spinner:         sp,
		filterBar:       components.NewFilterBarWithTokens([]components.FilterToken{{Label: problemsToken}}),
		checksTable: datatable.New(datatable.Config[netcheck.Check]{
			Columns: checkColumns(),
			// Pipeline order is content: resolve, reach, connect, TLS, HTTP is
			// the order the questions depend on one another. A table that
			// reorders itself destroys the one thing the layout says.
			SortColumn: -1,
		}),
	}
}

// NewWithTarget builds a view prefilled from an already-known target, for a
// producer elsewhere in the application (status's H, §3.66) rather than a
// user typing into the form. It stays a pure constructor — no tea.Cmd side
// effects — so the caller decides whether to also start the run, the same
// way uiviewer.NewWithSource hands back a model without loading anything.
=== update 10-95 ===
	"github.com/anthnel/devdesk/internal/netcheck"
	"github.com/anthnel/devdesk/internal/ui/components"
	"github.com/anthnel/devdesk/internal/ui/keymap"
)

// Init implements tea.Model
func (m *Model) Init() tea.Cmd {
	return tea.Batch(textinput.Blink, m.portsModel.initPorts(), m.interfacesModel.initInterfaces())
}

// InEditMode implements FormView — true when a text input is active, so the
// router hands the key to the field rather than opening the command line.
func (m *Model) InEditMode() bool {
	switch m.activeTab {
	case tabPorts:
		return m.portsModel.InEditMode()
	case tabInterfaces:
		// The interfaces table has a search box now, where the Topology tab it
		// replaced had no input at all. Returning false here would let a ":"
		// typed into the query open the command line instead (Rule 111).
		return m.interfacesModel.InEditMode()
	}
	if m.filterBar.InEditMode() {
		return true
	}
	if m.state == StateInput {
		return m.focusedField == fieldTarget || m.focusedField == fieldPort || m.focusedField == fieldDNSServer
	}
	return false
}

// FilterBarVisible implements app.FilterBarView.
func (m *Model) FilterBarVisible() bool {
	if m.activeTab == tabPorts {
		return m.portsModel.table.FilterBar().IsVisible()
	}
	return m.activeTab == tabDiagnostics && m.filterBar.IsVisible()
}

// Update implements tea.Model
func (m *Model) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
	switch msg := msg.(type) {
	case tea.WindowSizeMsg:
		m.width = msg.Width
		m.height = msg.Height
		m.resizeInputs()
		m.filterBar.Resize(msg.Width)
		m.rebuildChecksTable()
		m.resizeDetailsViewport()
		m.portsModel.resize(msg.Width, msg.Height)
		m.interfacesModel.resize(msg.Width, msg.Height)
		return m, nil

	case spinner.TickMsg:
		return m.handleSpinnerTick(msg)

	case stageDoneMsg:
		return m.handleStageDone(msg)

	// Ports sub-model messages. The confirm-modal answers are here because the
	// kill asks before it acts (§3.26), and the modal is the ports tab's.
	case portsTickMsg, portsDataMsg, portsKillResultMsg,
		components.ConfirmModalYesMsg, components.ConfirmModalNoMsg:
		var cmd tea.Cmd
		m.portsModel, cmd = m.portsModel.update(msg)
		return m, cmd

	// Topology sub-model messages
	case ifaceDataMsg:
		var cmd tea.Cmd
		m.interfacesModel, cmd = m.interfacesModel.update(msg)
		return m, cmd

	case tea.KeyMsg:
		return m.handleKey(msg)
	}

	// Each tab holds its own footer, so an expiry has to be offered to all
	// three: the timer fires wherever the user has since navigated.
	m.footer.Handle(msg)
	m.portsModel.footer.Handle(msg)
	m.interfacesModel.footer.Handle(msg)
	return m, nil
}

func (m *Model) handleSpinnerTick(msg spinner.TickMsg) (*Model, tea.Cmd) {

type Model struct {
	config *config.Config
	width  int
	height int

	// Active tab (tabDiagnostics, tabPorts, or tabInterfaces)
	activeTab       int
	portsModel      *PortsModel
	interfacesModel *InterfacesModel

	state ViewState

	// Form inputs
	targetInput    textinput.Model
	portInput      textinput.Model
	dnsServerInput textinput.Model
	focusedField   int

	// Running state
	spinner    spinner.Model
	runGen     int // incremented each run; results from a superseded run are dropped
	runStage   netcheck.StageID
	runStep    int
	totalSteps int

	// Results
	results     netcheck.Results
	verdict     netcheck.Verdict
	checksTable datatable.Model[netcheck.Check]
	filterBar   components.FilterBar

	// Details: one check explained
	detailsViewport viewport.Model
	selected        netcheck.Check

	// footer is the one line of transient state below the tab bar (Rule 128).
	footer components.FooterMessage

	// OriginView is where esc returns to from StateResults, when set. Empty
	// means netdiag was opened directly (the command line), and esc there
	// stays inside the view — resetting to the form, as it always has.
	OriginView command.ViewType
}

// New creates a new netdiag view
=== NewWithTarget ===
func NewWithTarget(cfg *config.Config, t netcheck.Target) *Model {
	m := New(cfg)
	m.targetInput.SetValue(t.Host)
	if t.Port > 0 {
		m.portInput.SetValue(strconv.Itoa(t.Port))
	}
	m.dnsServerInput.SetValue(t.Resolver)
	return m
}

// buildTarget assembles what the form describes.
func (m *Model) buildTarget() (netcheck.Target, error) {
	host := strings.TrimSpace(m.targetInput.Value())
	if err := validateTarget(host); err != nil {
		return netcheck.Target{}, err
	}
	port := strings.TrimSpace(m.portInput.Value())
	if port == "" {
		port = defaultPort
	}
	if err := validatePort(port); err != nil {
		return netcheck.Target{}, err
	}
	n, _ := strconv.Atoi(port) // validatePort has already accepted it
	return netcheck.Target{
		Host:     host,
		Port:     n,
		Resolver: strings.TrimSpace(m.dnsServerInput.Value()),
	}, nil
}

